select o.channel, case when o.shipping_fee >= 39 then 'high' when o.shipping_fee >= 14 then 'mid' else 'low' end as shipping_fee_bucket, min(oi.unit_price) as min_unit_price from order_items oi join orders o on oi.order_id = o.id join products p on oi.product_id = p.id group by o.channel, case when o.shipping_fee >= 39 then 'high' when o.shipping_fee >= 14 then 'mid' else 'low' end
